  "sections": [
    {"offset": {"line": 4, "column": 0}, "map": {"version":3,"sources":["file:///C:/Users/DELL/Desktop/Hotel%20Management/admin/src/app/page.js"],"sourcesContent":["\"use client\";\r\n\r\nimport { useState, useEffect } from \"react\";\r\nimport dynamic from \"next/dynamic\";\r\nimport { usePathname, useRouter } from \"next/navigation\";\r\nimport { Box, CircularProgress } from \"@mui/material\";\r\nimport { AppThemeProvider, useAppTheme } from \"@/shared/context/ThemeContext\";\r\nimport { SocketProvider } from \"@/shared/context/SocketContext\";\r\nimport UnifiedLogin from \"@/auth/components/UnifiedLogin\";\r\nimport SuperAdminLayout from \"@/super-admin/layout/SuperAdminLayout\";\r\nimport HotelAdminLayout from \"@/hotel-admin/layout/HotelAdminLayout\";\r\nimport ReceptionistLayout from \"@/receptionist/layout/ReceptionistLayout\";\r\nimport SuperAdminDashboard from \"@/super-admin/components/SuperAdminDashboard\";\r\nimport HotelAdminDashboard from \"@/hotel-admin/components/HotelAdminDashboard\";\r\nimport ReceptionistDashboard from \"@/receptionist/components/ReceptionistDashboard\";\r\n\r\nimport { API_ENDPOINTS, apiRequest } from \"@/config/api\";\r\nimport SubscriptionExpiredScreen from \"@/shared/components/SubscriptionExpiredScreen\";\r\n\r\nfunction AdminAppContent() {\r\n  const { themeConfig } = useAppTheme();\r\n  const pathname = usePathname();\r\n  const router = useRouter();\r\n\r\n  const getNavListForUser = (currentUser) => {\r\n    if (!currentUser) return [];\r\n    if (currentUser.role === \"HOTEL_ADMIN\") {\r\n      return [\"overview\", \"daily-collections\", \"guests\", \"staff\", \"rooms\", \"subscriptions\", \"settings\"];\r\n    }\r\n    if (currentUser.role === \"SUPER_ADMIN\") {\r\n      return [\"overview\", \"hotels\", \"approvals\", \"subscriptions\", \"audit-logs\", \"settings\"];\r\n    }\r\n    if (currentUser.role === \"RECEPTIONIST\") {\r\n      return [\"rooms\", \"folios\", \"check-in\", \"id-compliance\", \"pos-billing\", \"settings\"];\r\n    }\r\n    return [];\r\n  };\r\n\r\n  const getActiveTabFromPath = (currentUser, currentPath) => {\r\n    if (!currentUser) return 0;\r\n    const navList = getNavListForUser(currentUser);\r\n    const cleanPath = (currentPath || (typeof window !== \"undefined\" ? window.location.pathname : \"\"))\r\n      .replace(/^\\/+/, \"\")\r\n      .split(\"/\")[0] ||\r\n      (typeof window !== \"undefined\" ? window.location.hash.replace(\"#\", \"\").replace(/^\\/+/, \"\").split(\"/\")[0] : \"\");\r\n    \r\n    if (cleanPath) {\r\n      const idx = navList.indexOf(cleanPath);\r\n      if (idx !== -1) return idx;\r\n\r\n      // Common path aliases for seamless navigation\r\n      if (currentUser.role === \"RECEPTIONIST\") {\r\n        if (cleanPath === \"checkin\" || cleanPath === \"check-in\" || cleanPath === \"booking\") return 2;\r\n        if (cleanPath === \"id\" || cleanPath === \"kyc\" || cleanPath === \"compliance\") return 3;\r\n        if (cleanPath === \"pos\" || cleanPath === \"billing\") return 4;\r\n      }\r\n      if (currentUser.role === \"HOTEL_ADMIN\") {\r\n        if (cleanPath === \"collections\" || cleanPath === \"payments\" || cleanPath === \"billing\") return 1;\r\n        if (cleanPath === \"folios\" || cleanPath === \"guest-directory\") return 2;\r\n        if (cleanPath === \"team\") return 3;\r\n        if (cleanPath === \"plans\" || cleanPath === \"pricing\") return 5;\r\n      }\r\n    }\r\n    return 0;\r\n  };\r\n\r\n  const computeLockout = (userData) => {\r\n    if (!userData || userData.role === \"SUPER_ADMIN\") {\r\n      return { locked: false, type: \"EXPIRED\", reason: \"\" };\r\n    }\r\n\r\n    if (userData.status === \"INACTIVE\" || userData.status === \"BLOCKED\" || userData.status === \"DELETED\") {\r\n      return {\r\n        locked: true,\r\n        type: \"DISABLED\",\r\n        reason: \"Your staff account has been deactivated by Hotel Administration. All portal access is suspended.\",\r\n      };\r\n    }\r\n\r\n    const hotel = userData.hotel;\r\n    if (!hotel) return { locked: false, type: \"EXPIRED\", reason: \"\" };\r\n\r\n    if (hotel.status === \"DISABLED\" || hotel.status === \"SUSPENDED\") {\r\n      return {\r\n        locked: true,\r\n        type: hotel.status,\r\n        reason: hotel.statusReason || `Hotel account has been ${hotel.status.toLowerCase()} by Super Admin policy.`,\r\n      };\r\n    }\r\n\r\n    const sub = hotel.subscription;\r\n    if (sub) {\r\n      const now = new Date();\r\n      const trialEndDate = sub.trialEndDate ? new Date(sub.trialEndDate) : null;\r\n      const isTrialExpired = sub.isExpired || (sub.status === \"TRIAL\" && trialEndDate && trialEndDate < now) || sub.status === \"EXPIRED\";\r\n      if (isTrialExpired && sub.status !== \"ACTIVE\") {\r\n        return {\r\n          locked: true,\r\n          type: \"EXPIRED\",\r\n          reason: \"Your 30-day free trial or hotel subscription plan has ended.\",\r\n        };\r\n      }\r\n    }\r\n\r\n    return { locked: false, type: \"EXPIRED\", reason: \"\" };\r\n  };\r\n\r\n  // Instant synchronous state initialization from LocalStorage (Zero delay, Zero loader flash)\r\n  const [user, setUser] = useState(() => {\r\n    if (typeof window === \"undefined\") return null;\r\n    try {\r\n      const stored = localStorage.getItem(\"user\");\r\n      const token = localStorage.getItem(\"token\");\r\n      return stored && token ? JSON.parse(stored) : null;\r\n    } catch {\r\n      return null;\r\n    }\r\n  });\r\n\r\n  const [activeTab, setActiveTab] = useState(() => {\r\n    if (typeof window === \"undefined\") return 0;\r\n    try {\r\n      const stored = localStorage.getItem(\"user\");\r\n      const token = localStorage.getItem(\"token\");\r\n      const u = stored && token ? JSON.parse(stored) : null;\r\n      return getActiveTabFromPath(u, pathname);\r\n    } catch {\r\n      return 0;\r\n    }\r\n  });\r\n\r\n  const [lockout, setLockout] = useState(() => {\r\n    if (typeof window === \"undefined\") return { locked: false, type: \"EXPIRED\", reason: \"\" };\r\n    try {\r\n      const stored = localStorage.getItem(\"user\");\r\n      const token = localStorage.getItem(\"token\");\r\n      const u = stored && token ? JSON.parse(stored) : null;\r\n      return computeLockout(u);\r\n    } catch {\r\n      return { locked: false, type: \"EXPIRED\", reason: \"\" };\r\n    }\r\n  });\r\n\r\n  const checkUserLockout = (userData) => {\r\n    const res = computeLockout(userData);\r\n    setLockout(res);\r\n    return res.locked;\r\n  };\r\n\r\n  const handleLogout = () => {\r\n    try {\r\n      localStorage.removeItem(\"token\");\r\n      localStorage.removeItem(\"refreshToken\");\r\n      localStorage.removeItem(\"user\");\r\n    } catch {}\r\n    setUser(null);\r\n    setLockout({ locked: false, type: \"EXPIRED\", reason: \"\" });\r\n    setActiveTab(0);\r\n    router.push(\"/\");\r\n  };\r\n\r\n  useEffect(() => {\r\n    // Background silent profile verification without blocking UI\r\n    const token = localStorage.getItem(\"token\");\r\n    if (token) {\r\n      apiRequest(API_ENDPOINTS.AUTH.ME)\r\n        .then((res) => {\r\n          if (res?.data) {\r\n            setUser(res.data);\r\n            localStorage.setItem(\"user\", JSON.stringify(res.data));\r\n            checkUserLockout(res.data);\r\n          }\r\n        })\r\n        .catch(() => {});\r\n    }\r\n\r\n    // 1. Global listener for immediate lockout events triggered by apiRequest\r\n    const handleLockoutEvent = (e) => {\r\n      const detail = e.detail || {};\r\n      setLockout({\r\n        locked: true,\r\n        type: detail.hotelStatus || (detail.errorCode === \"SUBSCRIPTION_EXPIRED\" ? \"EXPIRED\" : \"DISABLED\"),\r\n        reason: detail.message || \"Hotel account access is restricted.\",\r\n      });\r\n    };\r\n\r\n    // 2. Global listener for Unauthorized 401 events (Auto-Logout on Token Expiry)\r\n    const handleUnauthorizedEvent = () => {\r\n      console.warn(\"🔒 [Auth] Session expired or unauthorized. Auto-logging out...\");\r\n      handleLogout();\r\n    };\r\n\r\n    // 3. Multi-Tab & Devtools Storage Listener (Auto-Logout if token is deleted)\r\n    const handleStorageEvent = (e) => {\r\n      if ((e.key === \"token\" || e.key === \"user\") && !e.newValue) {\r\n        console.warn(\"🔒 [Auth] Token removed from storage in another window. Auto-logging out...\");\r\n        handleLogout();\r\n      }\r\n      if (e.key === null) {\r\n        handleLogout();\r\n      }\r\n    };\r\n\r\n    // 4. Tab Focus & Periodic Check for Deleted Token\r\n    const handleFocusCheck = () => {\r\n      const currentToken = localStorage.getItem(\"token\");\r\n      if (!currentToken && localStorage.getItem(\"user\")) {\r\n        console.warn(\"🔒 [Auth] Token missing upon tab focus. Auto-logging out...\");\r\n        handleLogout();\r\n      }\r\n    };\r\n\r\n    const tokenHeartbeat = setInterval(() => {\r\n      const currentToken = localStorage.getItem(\"token\");\r\n      const currentStoredUser = localStorage.getItem(\"user\");\r\n      if (!currentToken && currentStoredUser) {\r\n        console.warn(\"🔒 [Auth] Token was deleted. Auto-logging out immediately...\");\r\n        handleLogout();\r\n      }\r\n    }, 2000);\r\n\r\n    window.addEventListener(\"hotel-status-lockout\", handleLockoutEvent);\r\n    window.addEventListener(\"auth-unauthorized\", handleUnauthorizedEvent);\r\n    window.addEventListener(\"storage\", handleStorageEvent);\r\n    window.addEventListener(\"focus\", handleFocusCheck);\r\n    document.addEventListener(\"visibilitychange\", handleFocusCheck);\r\n\r\n    return () => {\r\n      clearInterval(tokenHeartbeat);\r\n      window.removeEventListener(\"hotel-status-lockout\", handleLockoutEvent);\r\n      window.removeEventListener(\"auth-unauthorized\", handleUnauthorizedEvent);\r\n      window.removeEventListener(\"storage\", handleStorageEvent);\r\n      window.removeEventListener(\"focus\", handleFocusCheck);\r\n      document.removeEventListener(\"visibilitychange\", handleFocusCheck);\r\n    };\r\n  }, []);\r\n\r\n  // Keep activeTab synchronized with the browser URL address at all times\r\n  useEffect(() => {\r\n    if (user) {\r\n      const tabIdx = getActiveTabFromPath(user, pathname);\r\n      setActiveTab(tabIdx);\r\n    }\r\n  }, [pathname, user]);\r\n\r\n  const handleTabChange = (tabIndex) => {\r\n    setActiveTab(tabIndex);\r\n    if (user) {\r\n      const navList = getNavListForUser(user);\r\n      if (navList[tabIndex] !== undefined) {\r\n        const targetPath = tabIndex === 0 ? \"/\" : `/${navList[tabIndex]}`;\r\n        if (typeof window !== \"undefined\") {\r\n          window.history.pushState(null, \"\", targetPath);\r\n        }\r\n      }\r\n    }\r\n  };\r\n\r\n  return (\r\n    <>\r\n      {!user ? (\r\n        <UnifiedLogin\r\n          onLoginSuccess={(loggedInUser) => {\r\n            setUser(loggedInUser);\r\n            checkUserLockout(loggedInUser);\r\n          }}\r\n        />\r\n      ) : lockout.locked && user.role !== \"SUPER_ADMIN\" ? (\r\n        <SubscriptionExpiredScreen\r\n          user={user}\r\n          type={lockout.type}\r\n          reason={lockout.reason}\r\n          onLogout={handleLogout}\r\n        />\r\n      ) : (\r\n        <>\r\n          {user.role === \"SUPER_ADMIN\" && (\r\n            <SuperAdminLayout\r\n              user={user}\r\n              activeTab={activeTab}\r\n              onTabChange={handleTabChange}\r\n              onLogout={handleLogout}\r\n            >\r\n              <SuperAdminDashboard\r\n                user={user}\r\n                activeNav={activeTab}\r\n                onTabChange={handleTabChange}\r\n              />\r\n            </SuperAdminLayout>\r\n          )}\r\n\r\n          {user.role === \"HOTEL_ADMIN\" && (\r\n            <HotelAdminLayout\r\n              user={user}\r\n              activeTab={activeTab}\r\n              onTabChange={handleTabChange}\r\n              onLogout={handleLogout}\r\n            >\r\n              <HotelAdminDashboard\r\n                user={user}\r\n                activeNav={activeTab}\r\n                onTabChange={handleTabChange}\r\n              />\r\n            </HotelAdminLayout>\r\n          )}\r\n\r\n          {user.role === \"RECEPTIONIST\" && (\r\n            <ReceptionistLayout\r\n              user={user}\r\n              activeTab={activeTab}\r\n              onTabChange={handleTabChange}\r\n              onLogout={handleLogout}\r\n            >\r\n              <ReceptionistDashboard\r\n                user={user}\r\n                activeNav={activeTab}\r\n                onTabChange={handleTabChange}\r\n                onLogout={handleLogout}\r\n              />\r\n            </ReceptionistLayout>\r\n          )}\r\n        </>\r\n      )}\r\n    </>\r\n  );\r\n}\r\n\r\nexport default function Page() {\r\n  const [mounted, setMounted] = useState(false);\r\n\r\n  useEffect(() => {\r\n    setMounted(true);\r\n  }, []);\r\n\r\n  if (!mounted) {\r\n    return null;\r\n  }\r\n\r\n  return (\r\n    <AppThemeProvider>\r\n      <SocketProvider>\r\n        <AdminAppContent />\r\n      </SocketProvider>\r\n    </AppThemeProvider>\r\n  );\r\n}\r\n"],"names":["AdminAppContent","themeConfig","pathname","router","getNavListForUser","currentUser","role","getActiveTabFromPath","currentPath","navList","cleanPath","window","location","replace","split","hash","idx","indexOf","computeLockout","userData","locked","type","reason","status","hotel","statusReason","toLowerCase","sub","subscription","now","Date","trialEndDate","isTrialExpired","isExpired","user","setUser","stored","localStorage","getItem","token","JSON","parse","activeTab","setActiveTab","u","lockout","setLockout","checkUserLockout","res","handleLogout","removeItem","push","AUTH","ME","then","data","setItem","stringify","catch","handleLockoutEvent","e","detail","hotelStatus","errorCode","message","handleUnauthorizedEvent","console","warn","handleStorageEvent","key","newValue","handleFocusCheck","currentToken","tokenHeartbeat","setInterval","currentStoredUser","addEventListener","document","clearInterval","removeEventListener","tabIdx","handleTabChange","tabIndex","undefined","targetPath","history","pushState","onLoginSuccess","loggedInUser","onLogout","onTabChange","activeNav","Page","mounted","setMounted"],"mappings":";;;;;AAEA;AACA;AACA;AAEA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AAEA;AACA;;;AAjBA;;;;;;;;;;;;;;;;AAmBA,SAASA;;IACP,MAAM,EAAEC,WAAW,EAAE,GAAG,IAAA,2JAAW;IACnC,MAAMC,WAAW,IAAA,oJAAW;IAC5B,MAAMC,SAAS,IAAA,kJAAS;IAExB,MAAMC,oBAAoB,CAACC;QACzB,IAAI,CAACA,aAAa,OAAO,EAAE;QAC3B,IAAIA,YAAYC,IAAI,KAAK,eAAe;YACtC,OAAO;gBAAC;gBAAY;gBAAqB;gBAAU;gBAAS;gBAAS;gBAAiB;aAAW;QACnG;QACA,IAAID,YAAYC,IAAI,KAAK,eAAe;YACtC,OAAO;gBAAC;gBAAY;gBAAU;gBAAa;gBAAiB;gBAAc;aAAW;QACvF;QACA,IAAID,YAAYC,IAAI,KAAK,gBAAgB;YACvC,OAAO;gBAAC;gBAAS;gBAAU;gBAAY;gBAAiB;gBAAe;aAAW;QACpF;QACA,OAAO,EAAE;IACX;IAEA,MAAMC,uBAAuB,CAACF,aAAaG;QACzC,IAAI,CAACH,aAAa,OAAO;QACzB,MAAMI,UAAUL,kBAAkBC;QAClC,MAAMK,YAAY,CAACF,eAAe,CAAC,uCAAgCG,OAAOC,QAAQ,CAACV,QAAQ,GAAG,uBAAE,CAAC,EAC9FW,OAAO,CAAC,QAAQ,IAChBC,KAAK,CAAC,IAAI,CAAC,EAAE,IACd,CAAC,uCAAgCH,OAAOC,QAAQ,CAACG,IAAI,CAACF,OAAO,CAAC,KAAK,IAAIA,OAAO,CAAC,QAAQ,IAAIC,KAAK,CAAC,IAAI,CAAC,EAAE,GAAG,uBAAE;QAE/G,IAAIJ,WAAW;YACb,MAAMM,MAAMP,QAAQQ,OAAO,CAACP;YAC5B,IAAIM,QAAQ,CAAC,GAAG,OAAOA;YAEvB,8CAA8C;YAC9C,IAAIX,YAAYC,IAAI,KAAK,gBAAgB;gBACvC,IAAII,cAAc,aAAaA,cAAc,cAAcA,cAAc,WAAW,OAAO;gBAC3F,IAAIA,cAAc,QAAQA,cAAc,SAASA,cAAc,cAAc,OAAO;gBACpF,IAAIA,cAAc,SAASA,cAAc,WAAW,OAAO;YAC7D;YACA,IAAIL,YAAYC,IAAI,KAAK,eAAe;gBACtC,IAAII,cAAc,iBAAiBA,cAAc,cAAcA,cAAc,WAAW,OAAO;gBAC/F,IAAIA,cAAc,YAAYA,cAAc,mBAAmB,OAAO;gBACtE,IAAIA,cAAc,QAAQ,OAAO;gBACjC,IAAIA,cAAc,WAAWA,cAAc,WAAW,OAAO;YAC/D;QACF;QACA,OAAO;IACT;IAEA,MAAMQ,iBAAiB,CAACC;QACtB,IAAI,CAACA,YAAYA,SAASb,IAAI,KAAK,eAAe;YAChD,OAAO;gBAAEc,QAAQ;gBAAOC,MAAM;gBAAWC,QAAQ;YAAG;QACtD;QAEA,IAAIH,SAASI,MAAM,KAAK,cAAcJ,SAASI,MAAM,KAAK,aAAaJ,SAASI,MAAM,KAAK,WAAW;YACpG,OAAO;gBACLH,QAAQ;gBACRC,MAAM;gBACNC,QAAQ;YACV;QACF;QAEA,MAAME,QAAQL,SAASK,KAAK;QAC5B,IAAI,CAACA,OAAO,OAAO;YAAEJ,QAAQ;YAAOC,MAAM;YAAWC,QAAQ;QAAG;QAEhE,IAAIE,MAAMD,MAAM,KAAK,cAAcC,MAAMD,MAAM,KAAK,aAAa;YAC/D,OAAO;gBACLH,QAAQ;gBACRC,MAAMG,MAAMD,MAAM;gBAClBD,QAAQE,MAAMC,YAAY,IAAI,CAAC,uBAAuB,EAAED,MAAMD,MAAM,CAACG,WAAW,GAAG,uBAAuB,CAAC;YAC7G;QACF;QAEA,MAAMC,MAAMH,MAAMI,YAAY;QAC9B,IAAID,KAAK;YACP,MAAME,MAAM,IAAIC;YAChB,MAAMC,eAAeJ,IAAII,YAAY,GAAG,IAAID,KAAKH,IAAII,YAAY,IAAI;YACrE,MAAMC,iBAAiBL,IAAIM,SAAS,IAAKN,IAAIJ,MAAM,KAAK,WAAWQ,gBAAgBA,eAAeF,OAAQF,IAAIJ,MAAM,KAAK;YACzH,IAAIS,kBAAkBL,IAAIJ,MAAM,KAAK,UAAU;gBAC7C,OAAO;oBACLH,QAAQ;oBACRC,MAAM;oBACNC,QAAQ;gBACV;YACF;QACF;QAEA,OAAO;YAAEF,QAAQ;YAAOC,MAAM;YAAWC,QAAQ;QAAG;IACtD;IAEA,6FAA6F;IAC7F,MAAM,CAACY,MAAMC,QAAQ,GAAG,IAAA,yKAAQ;oCAAC;YAC/B;;YACA,IAAI;gBACF,MAAMC,SAASC,aAAaC,OAAO,CAAC;gBACpC,MAAMC,QAAQF,aAAaC,OAAO,CAAC;gBACnC,OAAOF,UAAUG,QAAQC,KAAKC,KAAK,CAACL,UAAU;YAChD,EAAE,OAAM;gBACN,OAAO;YACT;QACF;;IAEA,MAAM,CAACM,WAAWC,aAAa,GAAG,IAAA,yKAAQ;oCAAC;YACzC;;YACA,IAAI;gBACF,MAAMP,SAASC,aAAaC,OAAO,CAAC;gBACpC,MAAMC,QAAQF,aAAaC,OAAO,CAAC;gBACnC,MAAMM,IAAIR,UAAUG,QAAQC,KAAKC,KAAK,CAACL,UAAU;gBACjD,OAAO7B,qBAAqBqC,GAAG1C;YACjC,EAAE,OAAM;gBACN,OAAO;YACT;QACF;;IAEA,MAAM,CAAC2C,SAASC,WAAW,GAAG,IAAA,yKAAQ;oCAAC;YACrC;;YACA,IAAI;gBACF,MAAMV,SAASC,aAAaC,OAAO,CAAC;gBACpC,MAAMC,QAAQF,aAAaC,OAAO,CAAC;gBACnC,MAAMM,IAAIR,UAAUG,QAAQC,KAAKC,KAAK,CAACL,UAAU;gBACjD,OAAOlB,eAAe0B;YACxB,EAAE,OAAM;gBACN,OAAO;oBAAExB,QAAQ;oBAAOC,MAAM;oBAAWC,QAAQ;gBAAG;YACtD;QACF;;IAEA,MAAMyB,mBAAmB,CAAC5B;QACxB,MAAM6B,MAAM9B,eAAeC;QAC3B2B,WAAWE;QACX,OAAOA,IAAI5B,MAAM;IACnB;IAEA,MAAM6B,eAAe;QACnB,IAAI;YACFZ,aAAaa,UAAU,CAAC;YACxBb,aAAaa,UAAU,CAAC;YACxBb,aAAaa,UAAU,CAAC;QAC1B,EAAE,OAAM,CAAC;QACTf,QAAQ;QACRW,WAAW;YAAE1B,QAAQ;YAAOC,MAAM;YAAWC,QAAQ;QAAG;QACxDqB,aAAa;QACbxC,OAAOgD,IAAI,CAAC;IACd;IAEA,IAAA,0KAAS;qCAAC;YACR,6DAA6D;YAC7D,MAAMZ,QAAQF,aAAaC,OAAO,CAAC;YACnC,IAAIC,OAAO;gBACT,IAAA,qIAAU,EAAC,wIAAa,CAACa,IAAI,CAACC,EAAE,EAC7BC,IAA